            if (start + i) % n == 0:
                continue
            if moves[i] != moves[(start + i) % n]:
                return False
            count += 1
            if count >= 3:
                return True
        return False

    max_drunk = 0
    for start in range(n):
        if check(start):
            max_drunk += 1

    return max_drunk

