def max_juice(n, actions):
    dp = [0] * n
    dp[0] = 1 if actions[0] == 'b' else 0
    seen = {}

    for i in range(1, len(actions)):
        if actions[i] == 'b':
            dp[i] = dp[(i - 1) % n] + 1
        else:
            dp[i] = dp[(i - 1) % n]

        key = tuple(actions[max(0, i - 3):i])
        if key in seen:
            dp[i] = max(dp[i], dp[seen[key]] + 1)

        seen[key] = i

    return dp[-1]

